<?phpif (!defined('BASEPATH'))    exit('No direct script access allowed');class Soap_eresep extends MX_Controller{	var $session_name='sp';    function __construct()    {        parent::__construct();				#modules::run('auth/check_session');        $this->load->model('Soap_eresep_model');				$this->load->library('SmartLib');				date_default_timezone_set('Asia/Jakarta');    }	///////////////////	function prosesdetailobat(){		$id_obat    = $this->input->post('id_obat');		$datasett   = $this->Soap_eresep_model->detail_obatnya($id_obat);		$row_1      = $datasett->harga_margin;			$data = array(			'row_1'     => $row_1		);			$dataset = json_encode($data);		echo $dataset; 	}    	//////////////////	public function riwayat_resep($id_reg,$is_html=false)	{		$pasien = $this->smartlib->get_data_pasien_by_id_reg($id_reg);		$sql = "SELECT 	a.*,c.name AS nama_dokter, a.resepdate						FROM 		trx_frm_resep a										LEFT JOIN mst_dokter c ON (c.`id_dokter`=a.`id_dokter`)										,trx_reg b						WHERE		a.id_reg=b.id_reg										AND b.id_pasien='".$pasien['id_pasien']."'										AND a.cancel=0						ORDER BY a.resepdate DESC						LIMIT 10						";		#echo "<pre>".$sql."</pre>";		$query = $this->dbhis->query($sql);		$rs = $query->result_array();		foreach($rs as $k => $v)		{			switch($v['id_type'])			{				case '1':					$tipe_rawat = 'R.Jalan';					break;				case '2':					$tipe_rawat = 'R.Jalan';					break;				case '3':					$tipe_rawat = 'R.Jalan';					break;				default:					$tipe_rawat = 'R.Jalan';					break;			}			$rs[$k]['tipe_rawat'] = $tipe_rawat;		}		$data = array(			'rs' 						=> $rs,			'id_reg'				=> $id_reg		);		echo $this->load->view('riwayat_resep', $data, $is_html=true);	}	public function list_resep_baru_input($id_reg,$is_html=false)	{		$sql = "SELECT 	a.*,b.*						FROM 		soap_eresep a, soap_eresep_det b						WHERE 	a.id_eresep=b.id_eresep										AND a.id_reg='".$id_reg."'						";		$query = $this->dbhis->query($sql);		$rs_eresep_det = $query->result_array();		$data = array(			'rs_eresep_det'	=> $rs_eresep_det,			'id_reg'				=> $id_reg		);		return $this->load->view('list_resep_baru_input', $data,$is_html);	}	public function list_riwayat_resep_online($id_reg,$is_html=false,$id_pasien)	{		/*		$sql = "SELECT 	a.*,b.*						FROM 		soap_eresep a, trx_reg b						WHERE 	a.id_reg=b.id_reg AND b.id_pasien='".$id_pasien."'						ORDER BY a.id_eresep DESC						";		*/    //Query Asli PAk dadan		/*		$sql = "SELECT 	c.`id_dokter`,d.`name` AS nama_dokter,a.*,b.*						FROM 		soap_eresep a, trx_reg b, mst_dokter d										LEFT JOIN trx_reg_unit c ON (a.id_reg=c.id_reg AND c.`id_dokter`=d.`id_dokter`)						WHERE 	a.id_reg=b.id_reg AND b.id_pasien='".$id_pasien."'						ORDER BY a.id_eresep DESC						";		*/		/*    $sql = "SELECT ax.`id_dokter`,ax.nama_dokter, ax.*, ax.id_eresep, ax.eresepdate, ax.is_printed            FROM (              SELECT 	c.`id_dokter`,d.`name` AS nama_dokter,e.name as nama_dokter_ri              				,b.*, a.id_eresep, a.eresepdate, a.is_printed              FROM 		soap_eresep a              				LEFT JOIN trx_reg_unit c ON (a.id_reg=c.id_reg)                      LEFT JOIN mst_dokter d ON (c.`id_dokter`=d.`id_dokter`)                      ,trx_reg b                      LEFT JOIN mst_dokter e ON (b.`id_dokter_prt1`=e.`id_dokter`)              WHERE 	a.id_reg=b.id_reg              				AND b.id_pasien='".$id_pasien."'              UNION ALL              SELECT 	d.id_dokter, d.`name` AS nama_dokter, NULL AS nama_dokter_ri              				,b.*, a.id_eresep, a.eresepdate, a.is_printed              FROM 		soap_eresep a, trx_reg b, mst_dokter d              WHERE 	b.ugd = 1 AND b.status<2              				AND a.id_reg=b.id_reg              				AND b.`id_dokter_jaga`=d.`id_dokter`              				AND b.id_pasien='".$id_pasien."'            ) ax            ORDER BY ax.id_eresep DESC            ";		*/		// -------- NEW QUERY REBORN --------		$sql = "SELECT 	c.`id_dokter`										,(CASE WHEN f.`name` IS NOT NULL THEN f.`name`											WHEN d.`name` IS NOT NULL THEN d.`name`											ELSE e.name END) AS nama_dokter										,a.*,b.*						FROM 		soap_eresep a										LEFT JOIN mst_dokter f ON (f.`id_dokter`=a.`id_dokter`)										LEFT JOIN trx_reg_unit c ON (a.id_reg=c.id_reg AND DATE(a.eresepdate) = DATE(c.trxdate))										LEFT JOIN mst_dokter d ON (c.`id_dokter`=d.`id_dokter`)										, trx_reg b										LEFT JOIN mst_dokter e ON (e.`id_dokter`=b.`id_dokter_prt1`)						WHERE 	a.id_reg=b.id_reg AND b.id_pasien='".$id_pasien."'																ORDER BY a.id_eresep DESC";		/*		$sql = "SELECT ax.`id_dokter`,ax.nama_dokter, ax.*, ax.id_eresep, ax.eresepdate, ax.is_printed            FROM (              SELECT 	c.`id_dokter`,d.`name` AS nama_dokter,b.*, a.id_eresep, a.eresepdate, a.is_printed              FROM 		soap_eresep a, trx_reg b ,trx_reg_unit c, mst_dokter d              WHERE 	a.id_reg=b.id_reg              AND a.id_reg=c.id_reg AND c.`id_dokter`=d.`id_dokter`              AND b.id_pasien='".$id_pasien."'							AND DATE(a.eresepdate) = DATE(c.trxdate)              UNION ALL              SELECT d.id_dokter, d.`name` AS nama_dokter,b.*, a.id_eresep, a.eresepdate, a.is_printed              FROM soap_eresep a, trx_reg b, mst_dokter d              WHERE b.ugd = 1 AND b.status<2              AND a.id_reg=b.id_reg              AND b.`id_dokter_jaga`=d.`id_dokter`              AND b.id_pasien='".$id_pasien."'            ) ax            ORDER BY ax.id_eresep DESC            ";		*/		$query = $this->dbhis->query($sql);		$rs_eresep = $query->result_array();		foreach($rs_eresep as $k => $v)		{			if($v['rwjn']=='1')				$tipe_rawat = 'R.Jalan';			elseif($v['rwip']=='1')				$tipe_rawat = 'R.Jalan';			else				$tipe_rawat = 'R.Jalan';			$rs_eresep[$k]['tipe_rawat'] = $tipe_rawat;			### ----------------------------------------			if($v['is_printed']=='1')			{				#$rs_eresep[$k]['fungsi'] 							= 'Sudah diproses';				$rs_eresep[$k]['fungsi'] = '<a href="#" onClick="javascript : if(confirm(\'Batal eresep via telp?\')) cancel_eresep_by_phone(\''.$v['id_eresep'].'\');return false;">[ Hapus ]</a>';				$rs_eresep[$k]['bgcolor_riw_eresep'] 	= '#FFC09F';			}			else			{				$rs_eresep[$k]['fungsi'] = '<a href="#" onClick="javascript : hapus_eresep_hangat(\''.$v['id_eresep'].'\');return false;"><i class="fa fa-trash" style="color:red;"></i></a>';				$rs_eresep[$k]['bgcolor_riw_eresep'] 	= 'white';			}		}		$sql_check_id_resep = "SELECT id_eresep FROM soap_eresep WHERE id_reg='$id_reg'";		$queryideresep = $this->dbhis->query($sql_check_id_resep);		$eresepid = $queryideresep->result_array();		foreach($eresepid as $dtidresep){			$id_eresep = $dtidresep['id_eresep'];		}		$data = array(			'rs_eresep'		=> $rs_eresep,			'id_reg'		=> $id_reg,			'id_eresep'		=> $id_eresep		);		return $this->load->view('list_riwayat_resep_online', $data,$is_html);	}	public function list_riwayat_resep_online_farmasi($id_reg,$id_eresep,$is_html=false,$id_pasien)	{	$sql = "SELECT 	c.`id_dokter`	,(CASE WHEN f.`name` IS NOT NULL THEN f.`name`		WHEN d.`name` IS NOT NULL THEN d.`name`		ELSE e.name END) AS nama_dokter,a.*,b.*		FROM soap_eresep a			LEFT JOIN mst_dokter f ON (f.`id_dokter`=a.`id_dokter`)			LEFT JOIN trx_reg_unit c ON (a.id_reg=c.id_reg AND DATE(a.eresepdate) = DATE(c.trxdate))			LEFT JOIN mst_dokter d ON (c.`id_dokter`=d.`id_dokter`), trx_reg b			LEFT JOIN mst_dokter e ON (e.`id_dokter`=b.`id_dokter_prt1`)		WHERE a.id_reg=b.id_reg AND b.id_pasien='".$id_pasien."' ORDER BY a.id_eresep DESC";		$query = $this->dbhis->query($sql);		$rs_eresep = $query->result_array();		foreach($rs_eresep as $k => $v)		{			if($v['is_printed']=='1')			{				#$rs_eresep[$k]['fungsi'] 							= 'Sudah diproses';				$rs_eresep[$k]['fungsi'] = '<a href="#" onClick="javascript : if(confirm(\'Batal eresep via telp?\')) cancel_eresep_by_phone(\''.$v['id_eresep'].'\');return false;">[ Hapus ]</a>';				$rs_eresep[$k]['bgcolor_riw_eresep'] 	= '#FFC09F';			}			else			{				$rs_eresep[$k]['fungsi'] = '<a href="#" onClick="javascript : hapus_eresep_hangat(\''.$v['id_eresep'].'\');return false;"><i class="fa fa-trash" style="color:red;"></i></a>';				$rs_eresep[$k]['bgcolor_riw_eresep'] 	= 'white';			}		}		$data = array(			'rs_eresep'		=> $rs_eresep,			'id_reg'		=> $id_reg,			'id_eresep'		=> $id_eresep		);		return $this->load->view('list_riwayat_resep_online_farmasi', $data,$is_html);	}	public function list_riwayat_resep_online_det($id_eresep,$is_html=false,$is_print='f')	{		$sql = "SELECT 	a.*,b.*						FROM 		soap_eresep a, soap_eresep_det b						WHERE 	a.id_eresep=b.id_eresep										AND a.id_eresep='".$id_eresep."'										AND b.is_racikan=0										AND b.status=0						ORDER BY a.id_eresep DESC						";		$query = $this->dbhis->query($sql);		$rs_eresep_det = $query->result_array();		## ------ RACIKAN ----------------------------------------		# --- head ---		$sql = "SELECT 	a.*,b.*						FROM 		soap_eresep a, soap_eresep_det b						WHERE 	a.id_eresep=b.id_eresep										AND a.id_eresep='".$id_eresep."'										AND b.is_racikan=1										AND b.status=0						ORDER BY a.id_eresep DESC						";		$query = $this->dbhis->query($sql);		$rs_head = $query->result_array();		foreach($rs_head as $k_racikan => $v_racikan)		{			# --- detail ---			$sql = "SELECT 	b.*							FROM 		soap_eresep_det a, soap_eresep_det_racikan b							WHERE 	a.id_eresep_det=b.id_eresep_det							AND a.status=0							AND b.status=0											AND a.id_eresep_det='".$v_racikan['id_eresep_det']."'							";			$query = $this->dbhis->query($sql);			$rs_rck = $query->result_array();			$rs_head[$k_racikan]['det_racikan'] = $rs_rck;			#echo "<pre>".$sql."</pre>";		}		### --------- PERSIAPAN BUAT COPY OBAT ----------		$tr_obat_biasa = '';		foreach($rs_eresep_det as $k => $v)		{			$tr_obat_biasa .= '			var rand_no	= get_random_number();			var tpl_row_copy_biasa = \'\n\' +				\' <tr id="\'+ rand_no +\'">	 \n \' +				 \' <td>'.$v['name'].'<input type="hidden" name="ideresep[]" 				value="'.$id_eresep.'"><input type="hidden" name="obat[]" 				value="'.$v['name'].'"></td>	 \n \' +				 \' <td>'.$v['jenis_obat'].'				<input type="hidden" name="jenis_obat[]" 	value="'.$v['jenis_obat'].'">		 \n \' +				 \' 																<input type="hidden" name="id_fa[]" 			value="'.$v['id_trx_det'].'"></td>	\n \' +				 \' <td>							<input type="text" name="qty[]" 				value="'.$v['qty'].'" class="inp-short"></td>		\n \' +				 \' <td>						<input type="text" name="dosis[]" 			value="'.$v['dosis'].'" class="inp-medium"></td>		\n \' +				 \' <td>				<input type="text" name="frekwensi[]" 	value="'.$v['frekwensi'].'" class="inp-medium"></td>		\n \' +				 \' <td>				<input type="text" name="tme[]" 				value="'.$v['tme'].'" class="inp-medium"></td>		\n \' +				 \' <td>				<input type="text" name="note[]" 				value="'.$v['note'].'" class="inp-medium"></td>		\n \' +				 \' <td style="text-align:center;"><a href="#" onclick="javascript: if(confirm(\\\'Hapus ?\\\')) remove_row_draft(\\\'\'+ rand_no +\'\\\');return false;"><i class="fa fa-trash" style="color:red;"></i></a></td>		\n \' +				\' </tr>		\n \' ;				$( "#tbody_draft" ).append(tpl_row_copy_biasa);				$("#butt_simpan_resep").removeClass("hidden");				$("#batal_new_eresep").removeClass("hidden");			';		}		$tr_header_racikan = '';		foreach($rs_head as $k => $v)		{			$tr_header_racikan .= '				var id_num = $( "#id_num" ).val();				var num_resep_racikan = $( "#num_resep_racikan" ).val();				var tpl_row_copy = \'\n\' +					\' <tr id="row_racikan_\'+num_resep_racikan+\'"><td colspan="2">'.$v['name'].'	<input type="hidden" name="nama_racikan[\'+num_resep_racikan+\']" value="'.$v['name'].'"></td> \n \' +						\' <td>											<input type="text" name="jumlah_racikan[\'+num_resep_racikan+\']" value="'.$v['qty'].'" class="inp-short"></td> \n \' +						\' <td>											<input type="text" name="dosis_racikan[\'+num_resep_racikan+\']" value="'.$v['dosis'].'" class="inp-medium"></td> \n \' +						\' <td>											<input type="text" name="frekwensi_racikan[\'+num_resep_racikan+\']" value="'.$v['frekwensi'].'" class="inp-medium"></td> \n \' +						\' <td>											<input type="text" name="tme_racikan[\'+num_resep_racikan+\']" value="'.$v['tme'].'" class="inp-medium"></td> \n \' +						\' <td>											<input type="text" name="kemasan_racikan[\'+num_resep_racikan+\']" value="'.$v['jenis_obat'].'" class="inp-medium"></td> \n \' +						\' <td>											<input type="text" name="note_racikan[\'+num_resep_racikan+\']" value="'.$v['note'].'" class="inp-medium"></td> \n \' +						\' <td style="text-align:center;"><a href="#" onclick="javascript: if(confirm(\\\'Hapus ?\\\')) remove_row_resep_racikan(\\\'\'+num_resep_racikan+\'\\\');return false;"><i class="fa fa-trash" style="color:red;"></i></a></td> \n \' +					\' </tr>		\n \' ;				$("#tbody_draft_resep_racikan").append(tpl_row_copy);				console.log(id_num);				';				foreach($v['det_racikan'] as $kk => $vv)				{						$tr_header_racikan .= '							var tpl_row_copy = \'\n\' +										\'<tr class="row_racikan_det_\'+num_resep_racikan+\'">  \n \' +											\'<td>&nbsp;&nbsp;&nbsp;'.$vv['name'].'				<input type="hidden" name="det_racikan_obat[\'+num_resep_racikan+\']['.$kk.']" 	value="'.$vv['name'].'"></td>  	\n \' +											\'<td>&nbsp;&nbsp;&nbsp;'.$vv['jenis_obat'].'	<input type="hidden" name="det_jenis_obat[\'+num_resep_racikan+\']['.$kk.']" 		value="'.$vv['jenis_obat'].'">  	\n \' +											\'																						<input type="hidden" name="det_id_fa[\'+num_resep_racikan+\']['.$kk.']" 				value="'.$vv['id_trx_det'].'"></td>  	\n \' +											\'<td>				<input type="text" name="det_racikan_qty[\'+num_resep_racikan+\']['.$kk.']" 	value="'.$vv['qty'].'" class="inp-short"></td>  		\n \' +											\'<td colspan="5">&nbsp;</td>  \n \' +										\'</tr>		\n \' ;							$("#tbody_draft_resep_racikan").append(tpl_row_copy); ';				}				$tr_header_racikan .= '				$("#butt_simpan_resep").removeClass("hidden");				$("#batal_new_eresep").removeClass("hidden");				num_resep_racikan++;				$( "#num_resep_racikan" ).val(num_resep_racikan);				console.log(num_resep_racikan);				$("#id_num").val("0");			';		}		$data = array(			'rs_eresep_det'			=> $rs_eresep_det,			'id_eresep'					=> $id_eresep,			'rs_head'						=> $rs_head,			'tr_obat_biasa'			=> $tr_obat_biasa,			'tr_header_racikan'	=> $tr_header_racikan,		);		if($is_print=='t')			echo $this->load->view('list_riwayat_resep_online_det_print', $data,$is_html);		else			return $this->load->view('list_riwayat_resep_online_det', $data,$is_html);	}	public function list_riwayat_resep_farmasi_online_det($id_eresep,$is_html=false,$is_print='f')	{		$prd_m = date('m');		$prd_y = date('y');		$sql = "SELECT 	a.*,b.*,c.sale_price,d.qty_end		FROM soap_eresep a, soap_eresep_det b		LEFT JOIN mst_farmalkes c ON b.id_trx_det=c.id_fa		LEFT JOIN mst_farmalkes_avg d ON (c.id_fa=d.id_fa AND d.prd_m='$prd_m' AND d.prd_y='$prd_y')		WHERE a.id_eresep=b.id_eresep		AND a.id_eresep='".$id_eresep."'		AND b.is_racikan=0		ORDER BY a.id_eresep DESC";		$query = $this->dbhis->query($sql);		$rs_eresep_det = $query->result_array();		## ------ RACIKAN ----------------------------------------		# --- head ---		$sql = "SELECT 	a.*,b.*		FROM soap_eresep a, soap_eresep_det b		WHERE a.id_eresep=b.id_eresep 		AND a.id_eresep='".$id_eresep."'		AND b.is_racikan=1		ORDER BY a.id_eresep DESC";		$query = $this->dbhis->query($sql);		$rs_head = $query->result_array();		foreach($rs_head as $k_racikan => $v_racikan)		{			# --- detail ---			$sql = "SELECT b.*,c.sale_price,d.qty_end					FROM soap_eresep_det a, soap_eresep_det_racikan b					LEFT JOIN mst_farmalkes c ON b.id_trx_det=c.id_fa					LEFT JOIN mst_farmalkes_avg d ON (c.id_fa=d.id_fa AND d.prd_m='$prd_m' AND d.prd_y='$prd_y')					WHERE a.id_eresep_det=b.id_eresep_det					AND a.id_eresep_det='".$v_racikan['id_eresep_det']."'";			$query = $this->dbhis->query($sql);			$rs_rck = $query->result_array();			$rs_head[$k_racikan]['det_racikan'] = $rs_rck;			//echo "<pre>".$sql."</pre>";		}		### --------- PERSIAPAN BUAT COPY OBAT ----------		$tr_obat_biasa = '';		foreach($rs_eresep_det as $k => $v)		{			$tr_obat_biasa .= '			var rand_no	= get_random_number();			var tpl_row_copy_biasa = \'\n\' +				\' <tr id="\'+ rand_no +\'">	 \n \' +				 \' <td>'.$v['name'].'<input type="hidden" name="ideresep[]" value="'.$id_eresep.'"><input type="hidden" name="obat[]" value="'.$v['name'].'"></td>	 \n \' +				 \' <td>'.$v['jenis_obat'].' <input type="hidden" name="jenis_obat[]" 	value="'.$v['jenis_obat'].'">		 \n \' +				 \' <input type="hidden" name="id_fa[]" value="'.$v['id_trx_det'].'"></td> \n \' +				 \' <td><input type="text" name="qty[]" value="'.$v['qty'].'" class="inp-short"></td> \n \' +				 \' <td> <input type="text" name="dosis[]" value="'.$v['dosis'].'" class="inp-medium"></td> \n \' +				 \' <td> <input type="text" name="frekwensi[]" value="'.$v['frekwensi'].'" class="inp-medium"></td> \n \' +				 \' <td> <input type="text" name="tme[]" value="'.$v['tme'].'" class="inp-medium"></td> \n \' +				 \' <td> <input type="text" name="note[]" value="'.$v['note'].'" class="inp-medium"></td> \n \' +				 \' <td style="text-align:center;"><a href="#" onclick="javascript: if(confirm(\\\'Hapus ?\\\')) remove_row_draft(\\\'\'+ rand_no +\'\\\');return false;"><i class="fa fa-trash" style="color:red;"></i></a></td> \n \' +				\' </tr> \n \' ;				$( "#tbody_draft" ).append(tpl_row_copy_biasa);				$("#butt_simpan_resep").removeClass("hidden");				$("#batal_new_eresep").removeClass("hidden");			';		}		$tr_header_racikan = '';		foreach($rs_head as $k => $v)		{			$tr_header_racikan .= '				var id_num = $( "#id_num" ).val();				var num_resep_racikan = $( "#num_resep_racikan" ).val();				var tpl_row_copy = \'\n\' +					\' <tr id="row_racikan_\'+num_resep_racikan+\'"><td colspan="2">'.$v['name'].'	<input type="hidden" name="nama_racikan[\'+num_resep_racikan+\']" value="'.$v['name'].'"></td> \n \' +						\' <td>											<input type="text" name="jumlah_racikan[\'+num_resep_racikan+\']" value="'.$v['qty'].'" class="inp-short"></td> \n \' +						\' <td>											<input type="text" name="dosis_racikan[\'+num_resep_racikan+\']" value="'.$v['dosis'].'" class="inp-medium"></td> \n \' +						\' <td>											<input type="text" name="frekwensi_racikan[\'+num_resep_racikan+\']" value="'.$v['frekwensi'].'" class="inp-medium"></td> \n \' +						\' <td>											<input type="text" name="tme_racikan[\'+num_resep_racikan+\']" value="'.$v['tme'].'" class="inp-medium"></td> \n \' +						\' <td>											<input type="text" name="kemasan_racikan[\'+num_resep_racikan+\']" value="'.$v['jenis_obat'].'" class="inp-medium"></td> \n \' +						\' <td>											<input type="text" name="note_racikan[\'+num_resep_racikan+\']" value="'.$v['note'].'" class="inp-medium"></td> \n \' +						\' <td style="text-align:center;"><a href="#" onclick="javascript: if(confirm(\\\'Hapus ?\\\')) remove_row_resep_racikan(\\\'\'+num_resep_racikan+\'\\\');return false;"><i class="fa fa-trash" style="color:red;"></i></a></td> \n \' +					\' </tr>		\n \' ;				$("#tbody_draft_resep_racikan").append(tpl_row_copy);				console.log(id_num);				';				foreach($v['det_racikan'] as $kk => $vv)				{						$tr_header_racikan .= '							var tpl_row_copy = \'\n\' +										\'<tr class="row_racikan_det_\'+num_resep_racikan+\'">  \n \' +											\'<td>&nbsp;&nbsp;&nbsp;'.$vv['name'].'				<input type="hidden" name="det_racikan_obat[\'+num_resep_racikan+\']['.$kk.']" 	value="'.$vv['name'].'"></td>  	\n \' +											\'<td>&nbsp;&nbsp;&nbsp;'.$vv['jenis_obat'].'	<input type="hidden" name="det_jenis_obat[\'+num_resep_racikan+\']['.$kk.']" 		value="'.$vv['jenis_obat'].'">  	\n \' +											\'																						<input type="hidden" name="det_id_fa[\'+num_resep_racikan+\']['.$kk.']" 				value="'.$vv['id_trx_det'].'"></td>  	\n \' +											\'<td>				<input type="text" name="det_racikan_qty[\'+num_resep_racikan+\']['.$kk.']" 	value="'.$vv['qty'].'" class="inp-short"></td>  		\n \' +											\'<td colspan="5">&nbsp;</td>  \n \' +										\'</tr>		\n \' ;							$("#tbody_draft_resep_racikan").append(tpl_row_copy); ';				}				$tr_header_racikan .= '				$("#butt_simpan_resep").removeClass("hidden");				$("#batal_new_eresep").removeClass("hidden");				num_resep_racikan++;				$( "#num_resep_racikan" ).val(num_resep_racikan);				console.log(num_resep_racikan);				$("#id_num").val("0");			';		}		$data = array(			'rs_eresep_det'			=> $rs_eresep_det,			'id_eresep'					=> $id_eresep,			'rs_head'						=> $rs_head,			'tr_obat_biasa'			=> $tr_obat_biasa,			'tr_header_racikan'	=> $tr_header_racikan,		);		if($is_print=='t')			echo $this->load->view('list_riwayat_resep_online_det_print', $data,$is_html);		else			return $this->load->view('list_riwayat_resep_farmasi_online_det', $data,$is_html);	}	public function inner_resep_detail($id_resep)	{		$sql = "SELECT 	a.*,b.name AS frekwensi,c.amount AS dosis,d.time AS time_time,d.`name` AS time_name										,e.`id_src`						FROM 		trx_frm_resep_det a										LEFT JOIN `mst_farmalkes_etk_day` b ON (a.`qty_day`=b.`id`)										LEFT JOIN `mst_farmalkes_etk_amt` c ON (a.`id_amt`=c.`id_amt`)										LEFT JOIN `mst_farmalkes_etk_tme` d ON (a.`id_time`=d.`id_time`)										,`mst_farmalkes` e						WHERE 	a.`id_trx_det`=e.`id_fa`										AND a.id_resep='".$id_resep."'						";		$query = $this->dbhis->query($sql);		$rs = $query->result_array();		$jenis_obat[0] = 'Oral';		$jenis_obat[1] = 'Obat Luar';		foreach($rs as $k => $v)		{			$rs[$k]['jenis_obat'] = $jenis_obat[$v['id_src']];		}		$data = array(			'rs' 			=> $rs,		);		echo $this->load->view('riwayat_resep_det', $data, true);	}	public function add_new()	{		$id_reg	                      = $this->input->post('id_reg');		$data_pasien	= $this->smartlib->get_data_pasien_by_id_reg($id_reg);		$id_pasien = $data_pasien['id_pasien'];		#$id_reg = $this->input->get('id_reg',true);		$list_riwayat_resep_online = $this->list_riwayat_resep_online($id_reg,$is_html=true,$id_pasien);		$data = array(			'id_reg'								=> $id_reg,			'id_pasien'								=> $id_pasien,			'list_riwayat_resep_online'	=> $list_riwayat_resep_online		);		$this->load->view('eresep_add', $data);	}	public function add_additional()	{		$id_reg	                      = $this->input->post('id_reg');		$id_eresep	                  = $this->input->post('id_eresep');		$data_pasien	= $this->smartlib->get_data_pasien_by_id_reg($id_reg);		$id_pasien = $data_pasien['id_pasien'];		#$id_reg = $this->input->get('id_reg',true);		$list_riwayat_resep_online = $this->list_riwayat_resep_online_farmasi($id_reg,$id_eresep,$is_html=true,$id_pasien);		$data = array(			'id_reg'								=> $id_reg,			'id_pasien'								=> $id_pasien,			'id_eresep'								=> $id_eresep,			'list_riwayat_resep_online'	=> $list_riwayat_resep_online		);		$this->load->view('eresep_additional', $data);	}	public function inner_get_data_autocomplet_obat()	{		$term = $this->input->get('term',true);		$sql = "SELECT 	a.id_fa,a.`name`,a.id_src						FROM 		mst_farmalkes a						WHERE 	UPPER(a.name) LIKE '%".strtoupper($term)."%'										AND a.aktif = 1						";		$query = $this->dbhis->query($sql);		$rs = $query->result_array();		$jenis_obat[0] = 'Oral';		$jenis_obat[1] = 'Obat Luar';		foreach($rs as $k => $v)		{			$rs[$k]['jenis_obat'] = $jenis_obat[$v['id_src']];			$rs[$k]['label'] = $v['name'];			$rs[$k]['id'] = $v['id_fa'];		}		$obat = json_encode($rs);		echo $obat;	}	public function inner_get_data_autocomplet_obat_dosis()	{		$term = $this->input->get('term',true);		$sql = "SELECT 	a.`id_amt` AS id										,CONCAT(a.`amount`,' ',a.`satuan`) AS label						FROM		`mst_farmalkes_etk_amt` a						WHERE 	a.`aktif`=1 AND UPPER(CONCAT(a.`amount`,' ',a.`satuan`)) LIKE '%".strtoupper($term)."%'						ORDER BY a.`satuan`,a.`amount`						";		$query = $this->dbhis->query($sql);		$rs = $query->result_array();		$dosis = json_encode($rs);		echo $dosis;	}	public function inner_get_data_autocomplet_obat_frekwensi()	{		$term = $this->input->get('term',true);		$sql = "SELECT 	a.`id`,a.`name` AS label						FROM		`mst_farmalkes_etk_day` a						ORDER BY a.name						";		$query = $this->dbhis->query($sql);		$rs = $query->result_array();		$frekwensi = json_encode($rs);		echo $frekwensi;	}	public function inner_get_data_autocomplet_obat_tme()	{		$term = $this->input->get('term',true);		$sql = "SELECT 	DISTINCT a.`id_time` AS id										,a.`name` AS label						FROM		`mst_farmalkes_etk_tme` a						WHERE 	a.`aktif`=1 AND UPPER(a.`name`) LIKE '%".strtoupper($term)."%'						ORDER BY a.`name`						";		$query = $this->dbhis->query($sql);		$rs = $query->result_array();		$tme = json_encode($rs);		echo $tme;	}	public function inner_get_data_autocomplet_nama_dokter()	{		$term = $this->input->get('term',true);		$sql = "SELECT 	a.`id_dokter` AS id,a.`name` AS label						FROM		`mst_dokter` a						WHERE 	UPPER(a.`name`) LIKE '%".strtoupper($term)."%'						ORDER BY a.`name`						";		$query = $this->dbhis->query($sql);		$rs = $query->result_array();		$dokter = json_encode($rs);		echo $dokter;	}	public function save_eresep()	{		## --- data header ---		$id_reg = $this->input->post('id_reg',true);		$id_pasien = $this->input->post('id_pasien',true);		$now = date('Y-m-d H:i:s');		$is_eresep_pulang = intval($this->input->post('is_eresep_pulang',true));		## --- data detail ---		$obat 			= $this->input->post('obat',true);		$id_fa 			= $this->input->post('id_fa',true);		$jenis_obat = $this->input->post('jenis_obat',true);		$qty 				= $this->input->post('qty',true);		$harga 				= $this->input->post('harga',true);		$subtotal 				= $this->input->post('subtotal',true);		$dosis 			= $this->input->post('dosis',true);		$frekwensi 	= $this->input->post('frekwensi',true);		$tme 				= $this->input->post('tme',true);		$note 			= $this->input->post('note',true);		## ---  data racikan ; headernya ------------------		$nama_racikan 			= $this->input->post('nama_racikan',true);		$jumlah_racikan 	= $this->input->post('jumlah_racikan',true);		$dosis_racikan 	= $this->input->post('dosis_racikan',true);		$frekwensi_racikan 	= $this->input->post('frekwensi_racikan',true);		$tme_racikan 				= $this->input->post('tme_racikan',true);		$kemasan_racikan 		= $this->input->post('kemasan_racikan',true);		$note_racikan 			= $this->input->post('note_racikan',true);		## contoh format : nama_racikan[0]		## ---  data racikan detail ; detailnya ------------------		$det_racikan_obat 	= $this->input->post('det_racikan_obat',true);		$det_id_fa 		= $this->input->post('det_id_fa',true);		$det_jenis_obat 		= $this->input->post('det_jenis_obat',true);		$det_racikan_qty 		= $this->input->post('det_racikan_qty',true);		$det_racikan_harga 		= $thi