						, `note`									, `is_racikan`)												VALUES 	('".$id_eresep."'	, 0							, '".$v."'	, '".$kemasan_racikan[$k]."'	, '".$jumlah_racikan[$k]."'			, '".$dosis_racikan[$k]."'	, '".$tme_racikan[$k]."'	, '".$frekwensi_racikan[$k]."'	, '".$note_racikan[$k]."'	, 1 	)";				$ok = $this->dbhis->query($sql_insert_det);				### --- GET id_eresep ---------------------------------				$sql 						= "SELECT LAST_INSERT_ID() as id_eresep_det";				$query 					= $this->dbhis->query($sql);				$rs 						= $query->row_array();				$id_eresep_det 	= $rs['id_eresep_det'];				foreach($det_racikan_obat[$k] as $kk => $vv)				{					/*					$sql_insert_det_racikan = "INSERT INTO `soap_eresep_det_racikan` (																			`id_eresep_det`			,`id_eresep`			,`id_trx_det`							,`name`			,`jenis_obat`										,`qty`													,`dosis`)														VALUES 	(	'".$id_eresep_det."','".$id_eresep."'	,'".$det_id_fa[$k][$kk]."','".$vv."'	,'".$det_jenis_obat[$k][$kk]."'	,'".$det_racikan_qty[$k][$kk]."','".$det_racikan_dosis[$k][$kk]."')					";					*/					$sql_insert_det_racikan = "INSERT INTO `soap_eresep_det_racikan` (																			`id_eresep_det`			,`id_eresep`			,`id_trx_det`							,`name`			,`jenis_obat`										,`qty`,`harga_satuan`,`subtotal`)														VALUES 	(	'".$id_eresep_det."','".$id_eresep."'	,'".$det_id_fa[$k][$kk]."','".$vv."'	,'".$det_jenis_obat[$k][$kk]."'	,'".$det_racikan_qty[$k][$kk]."', '".$det_racikan_harga[$k][$kk]."', '".$det_racikan_subtotal[$k][$kk]."')					";					$ok = $this->dbhis->query($sql_insert_det_racikan);				}			}		}		echo "<script language=\"javascript\">swal.fire('Berhasil!','Resep Berhasil Dibuat!', 'success')</script>";				#$pasien = $this->smartlib->get_data_pasien_by_id_reg($id_reg);		#redirect('soap/epoli/pasien_list/'.$id_reg.'/'.$pasien['id_pasien']."#plan4");		#echo $this->list_resep_baru_input($id_reg,true);		echo $this->add_new($id_reg,$id_pasien);	}	public function save_e