odedokter 										,(CASE WHEN b.rwip=1 THEN 'RI' ELSE 'RJ' END) AS tipe_rawat						FROM 		soap_eresep a										LEFT JOIN mst_dokter h ON (h.`id_dokter`=a.`id_dokter`)										LEFT JOIN smart_login k ON (k.`id_dokter`=a.`id_dokter`)										,trx_reg b										LEFT JOIN trx_reg_unit c ON (c.id_reg=b.id_reg)										LEFT JOIN mst_dokter e ON (e.`id_dokter`=c.`id_dokter`)										LEFT JOIN smart_login i ON (i.`id_dokter`=c.`id_dokter`)										LEFT JOIN mst_dokter f ON (f.`id_dokter`=b.`id_dokter_jaga`)										LEFT JOIN smart_login j ON (j.`id_dokter`=b.`id_dokter_jaga`)										,mst_pasien d						WHERE 	a.id_reg=b.id_reg AND b.id_pasien=d.id_pasien										AND a.id_eresep='".$id_eresep."'";		$query 	= $this->dbhis->query($sql);		$rs 		= $query->row_array();    $id_reg = $rs['id_reg'];    $id_pasien = $rs['id_pasien'];		$tipe_rawat = $rs['tipe_rawat'];    $riwayat_pasien 	= $this->smartlib->riwayat_pasien($id_pasien);		$pasien = $this->smartlib->get_data_registrasi_by_id_reg($id_reg);		if($tipe_rawat=='RI')		{    	$alergi = $this->smartlib->get_alergi_pasien_ri($id_reg);			$pasien['poli_ruangan'] = $this->smartlib->get_ruangan_pasien($id_reg);		}		else		{			$alergi = $this->smartlib->get_alergi_pasien_rj_igd($id_reg);		}		$soap 	= $this->Soap_eresep_model->get_data_soap($id_reg);		$sql 		= "SELECT a.* FROM soap_eresep_det a WHERE a.id_eresep='".$id_eresep."'";		$query 	= $this->dbhis->query($sql);		$rs_det = $query->result_array();		$jum_resep = $query->num_rows();		foreach($rs_det as $k => $v)		{			$rs_det[$k]['qty_romawi']	= $this->numberToRomanRepresentation($v['qty']);			$rs_det[$k]['name_alt'] = $this->frekwensi2name_alt($v['frekwensi']);			if($v['is_racikan']==1)			{				$sql 						= "SELECT a.* FROM soap_eresep_det_racikan a WHERE a.id_eresep_det='".$v['id_eresep_det']."'";				$query 					= $this->dbhis->query($sql);				$rs_det_racikan = $query->result_array();				$rs_det[$k]['racikan'] = $rs_det_racikan;			}		}		// -- UPDATE yg sudah diprint --		$sql = "UPDATE soap_eresep SET is_printed=1 WHERE id_eresep='".$id_eresep."'";		$query 	= $this->dbhis->query($sql);		$this->antrolib->updateWaktuAntreanWithIdreg($id_reg, $rs['kodedokter'], 6);		$this->antrolib->updateWaktuAntreanWithIdreg($id_reg, $rs['kodedokter'], 7);		$data = array(			'rs' 		=> $rs,			'rs_det' 	=> $rs_det,			'jum_resep'	=> $jum_resep,			'pasien'	=> $pasien,			'soap'		=> $soap,      'alergi'		=> $alergi,			'nama_rs'		=> $nama_rs,			'alamat_rs'	=> $alamat_rs,			'telp_rs'		=> $telp_rs,			'fax_rs'		=> $fax_rs,      'riwayat_pasien'	=> $riwayat_pasien,		);		$this->load->view('print_eresep', $data);	}	function frekwensi2name_alt($frek)	{		$sql = "SELECT a.name_alt FROM mst_farmalkes_etk_day a WHERE name = '".$frek."'";		$query 			= $this->dbhis->query($sql);		$rs 				= $query->row_array();		$name_alt 	= $rs['name_alt'];		if($name_alt!='')			$name_alt = $name_alt;		else			$name_alt = $frek;		return $name_alt;	}	function numberToRomanRepresentation($number)	{		$map = array('M' => 1000, 'CM' => 900, 'D' => 500, 'CD' => 400, 'C' => 100, 'XC' => 90, 'L' => 50, 'XL' => 40, 'X' => 10, 'IX' => 9, 'V' => 5, 'IV' => 4, 'I' => 1);		$returnValue = '';		while ($number > 0) {				foreach ($map as $roman => $int) {						if($number >= $int) {								$number -= $int;								$returnValue .= $roman;								break;						}				}		}		return $returnValue;	}	public function mst_tpl_racikan()	{		$id_dokter = $this->session->userdata['sp']->id_dokter;		$this->make_bread->add('Master Admin', '', 1);    $this->make_bread->add('Template Racikan', '', 0);    $breadcrumb = $this->make_bread->output();		$sql = "SELECT 	a.*,b.name AS nama_dokter						FROM 		soap_eresep_tpl_racikan a										LEFT JOIN mst_dokter b ON (a.id_dokter=b.id_dokter)						WHERE b.aktif = 1						";		if($id_dokter!='')			$sql .= " AND a.id_dokter=".$id_dokter." ";		$query = $this->dbhis->query($sql);		$rs = $query->result();		$data = array(			'rs' 	=> $rs,			'breadcrumb' 	=> $breadcrumb,		);		$this->load->view('vmst_tpl_racikan', $data);	}	public function mst_tpl_racikan_add()	{		$this->make_bread->add('Dokter', '', 1);    $this->make_bread->add('Master Template Racikan', '', 0);    $breadcrumb = $this->make_bread->output();		$data = array(			'breadcrumb'	=> $breadcrumb,		);		$this->load->view('vmst_tpl_racikan_add', $data);	}	public function mst_tpl_racikan_save_new()	{		#$this->output->enable_profiler(true);		## --- other ---		$now = date('Y-m-d H:i:s');		## --- data header racikan ---		$id_dokter 			= $this->input->post('id_dokter',true);		$nama_racikan 	= $this->input->post('nama_racikan',true);		$kemasan 				= $this->input->post('kemasan',true);		$jumlah_tpl 		= $this->input->post('jumlah_tpl',true);		$frekwensi_tpl 	= $this->input->post('frekwensi_tpl',true);		$tme_tpl 				= $this->input->post('tme_tpl',true);		$note_tpl 			= $this->input->post('note_tpl',true);		$dosis_tpl 			= $this->input->post('dosis_tpl',true);		## --- data detail ---		$obat 			= $this->input->post('obat',true);		$id_fa 			= $this->input->post('id_fa',true);		$jenis_obat = $this->input->post('jenis_obat',true);		$qty 				= $this->input->post('qty',true);		### --- INSERT tpl_racikan ---------------------------------		$sql_insert_header = "	INSERT INTO `soap_eresep_tpl_racikan`																	(`id_dokter`,`nama_racikan`,`frekwensi`,`tme`,`note`,`kemasan`,`dosis`,`jumlah`)														VALUES																	('".$id_dokter."', '".$nama_racikan."', '".$frekwensi_tpl."','".$tme_tpl."', '".$note_tpl."','".$kemasan."','".$dosis_tpl."','".$jumlah_tpl."')";		$ok = $this->dbhis->query($sql_insert_header);		### --- GET id_tpl_racikan -----------------------------