ELECT 1 FROM soap_eresep_det x WHERE x.is_racikan=1 AND x.id_eresep=a.id_eresep LIMIT 1) AS is_racikan										,g.name AS penjamin						FROM 		soap_eresep a										LEFT JOIN mst_dokter h ON (h.`id_dokter`=a.`id_dokter`)										LEFT JOIN trx_reg_unit c ON (c.id_reg=a.id_reg AND DATE(a.eresepdate) = DATE(c.trxdate))										LEFT JOIN mst_dokter e ON (e.`id_dokter`=c.`id_dokter`)										,trx_reg b										LEFT JOIN mst_company g ON (g.id_company=b.id_asuransi)										LEFT JOIN mst_dokter f ON (f.`id_dokter`=b.`id_dokter_jaga`)										,mst_pasien d						WHERE 	a.id_reg=b.id_reg AND b.id_pasien=d.id_pasien										AND a.`eresepdate` >= (NOW() - INTERVAL 12 HOUR)																				";														$sql .= ($tipe=='rj') ? " AND b.rwip=0 " : " AND b.rwip=1 ";		$sql .= "					ORDER BY a.id_eresep DESC ";		#echo "<pre>".$sql."</pre>";		$query = $this->dbhis->query($sql);		$rs = $query->result_array();		foreach($rs as $k => $v)		{			if($v['is_printed']=='1')				$bgcolor = '#F4BCBD';			else				$bgcolor = '';			$rs[$k]['bgcolor'] = $bgcolor;			$rs[$k]['jenis_kemasan'] = ($v['is_racikan']=='1')?'Racikan':'Non - Racikan';		}		$text_tipe['rj'] = "Rawat Jalan";		$text_tipe['ri'] = "Rawat Inap";		$data = array(			'rs' 		=> $rs,			'text_tipe'	=> $text_tipe[$tipe],		);		$this->load->view('display_eresep_farmasi', $data);	}	public function display_eresep_farmasi_cari_xxx()	{		$id_pasien_cari		= $this->input->get('id_pasien_cari');		$nama_pasien_cari	= $this->input->get('nama_pasien_cari');		$this->make_bread->add('Farmasi', '', 1);    $this->make_bread->add('Pencarian Resep', '', 0);    $breadcrumb = $this->make_bread->output();		if(empty($id_pasien_cari) && empty($nama_pasien_cari))		{			$data = array(				'rs'								=> array(),				'id_pasien_cari'		=> $id_pasien_cari,				'nama_pasien_cari' 	=> $nama_pasien_cari,				'breadcrumb' 				=> $breadcrumb,			);			$this->load->view('display_eresep_farmasi_cari',$data);			return;		}		$sql = "SELECT 	a.*,b.id_pasien,d.name AS nama_pasien, IFNULL(e.`name`, f.`name`) AS dokter										,(SELECT 1 FROM soap_eresep_det x WHERE x.is_racikan=1 AND x.id_eresep=a.id_eresep LIMIT 1) AS is_racikan										,g.name AS penjamin						FROM 		soap_eresep a										,trx_reg b										LEFT JOIN mst_company g ON (g.id_company=b.id_asuransi)										LEFT JOIN trx_reg_unit c ON (c.id_reg=b.id_reg)										LEFT JOIN mst_dokter e ON (e.`id_dokter`=c.`id_dokter`)										LEFT JOIN mst_dokter f ON (f.`id_dokter`=b.`id_dokter_jaga`)										,mst_pasien d						WHERE 	a.id_reg=b.id_reg AND b.id_pasien=d.id_pasien										";			if($id_pasien_cari != '')				$sql.=" AND b.id_pasien =".intval($id_pasien_cari)."				";			if ($nama_pasien_cari != '')				$sql.=" AND LOWER(b.name) LIKE LOWER('%".$nama_pasien_cari."%')				";		$sql .= " ORDER BY a.id_eresep DESC							LIMIT 100						";		#echo "<pre>".$sql."</pre>";		$query = $this->dbhis->query($sql);		$rs = $query->result_array();		foreach($rs as $k => $v)		{			if($v['is_printed']=='1')				$bgcolor = '#F4BCBD';			else				$bgcolor = '';			$rs[$k]['bgcolor'] = $bgcolor;			$rs[$k]['jenis_kemasan'] = ($v['is_racikan']=='1')?'Racikan':'Non - Racikan';		}		$data = array(			'rs' 	=> $rs,			'breadcrumb' 	=> $breadcrumb,		);		$this->load->view('display_eresep_farmasi_cari', $data);	}	public function display_eresep_farmasi_cari()	{		$id_pasien_cari		= $this->input->post('id_pasien_cari');		$nama_pasien_cari	= $this->input->post('nama_pasien_cari');		$this->make_bread->add('Farmasi', '', 1);    $this->make_bread->add('Pencarian Resep', '', 0);    $breadcrumb = $this->make_bread->output();		if(empty($id_pasien_cari) && empty($nama_pasien_cari))		{			$data = array(				'rs'								=> array(),				'id_pasien_cari'		=> $id_pasien_cari,				'nama_pasien_ca