y($sql);			$sql = "DELETE FROM soap_eresep_tpl_racikan WHERE id_tpl_racikan='".$id_tpl_racikan."'";			$ok2 = $this->dbhis->query($sql);			$oke = 'ok';		}		echo $oke;	}	public function list_riwayat_resep_online_v2($id_reg,$id_pasien)	{		/*		$sql = "SELECT 	a.*,b.*						FROM 		soap_eresep a, trx_reg b						WHERE 	a.id_reg=b.id_reg AND b.id_pasien='".$id_pasien."'						ORDER BY a.id_eresep DESC						";		*/    //Query Asli PAk dadan		// $sql = "SELECT 	c.`id_dokter`,d.`name` AS nama_dokter,a.*,b.*		// 				FROM 		soap_eresep a, trx_reg b		// 								,trx_reg_unit c, mst_dokter d		// 				WHERE 	a.id_reg=b.id_reg AND b.id_pasien='".$id_pasien."'		// 								AND a.id_reg=c.id_reg AND c.`id_dokter`=d.`id_dokter`		// 				ORDER BY a.id_eresep DESC		// 				";    $sql = "SELECT ax.`id_dokter`,ax.nama_dokter, ax.*, ax.id_eresep, ax.eresepdate, ax.is_printed            FROM (              SELECT 	c.`id_dokter`,d.`name` AS nama_dokter,e.name as nama_dokter_ri              				,b.*, a.id_eresep, a.eresepdate, a.is_printed											,a.is_eresep_pulang              FROM 		soap_eresep a              				LEFT JOIN trx_reg_unit c ON (a.id_reg=c.id_reg)                      LEFT JOIN mst_dokter d ON (c.`id_dokter`=d.`id_dokter`)                      ,trx_reg b                      LEFT JOIN mst_dokter e ON (b.`id_dokter_prt1`=e.`id_dokter`)              WHERE 	a.id_reg=b.id_reg              				AND b.id_pasien='".$id_pasien."'              UNION ALL              SELECT 	d.id_dokter, d.`name` AS nama_dokter, NULL AS nama_dokter_ri              				,b.*, a.id_eresep, a.eresepdate, a.is_printed											,a.is_eresep_pulang              FROM 		soap_eresep a, trx_reg b, mst_dokter d              WHERE 	b.ugd = 1 AND b.status<2              				AND a.id_reg=b.id_reg              				AND b.`id_dokter_jaga`=d.`id_dokter`              				AND b.id_pasien='".$id_pasien."'            ) ax            ORDER BY ax.id_eresep DESC            ";		$query = $this->dbhis->query($sql);		$rs_eresep = $query->result_array();		foreach($rs_eresep as $k => $v)		{			if($v['rwjn']=='1')				$tipe_rawat = 'R.Jalan';			elseif($v['rwip']=='1')				$tipe_rawat = 'R.Jalan';			else				$tipe_rawat = 'R.Jalan';			$rs_eresep[$k]['tipe_rawat'] = $tipe_rawat;			### ----------------------------------------			/*			if($v['is_printed']=='1')			{				#$rs_eresep[$k]['fungsi'] 							= 'Sudah diproses';				$rs_eresep[$k]['fungsi'] = '<a href="#" onClick="javascript : if(confirm(\'Batal eresep via telp?\')) cancel_eresep_by_phone(\''.$v['id_eresep'].'\');return false;">[ Hapus ]</a>';				$rs_eresep[$k]['bgcolor_riw_eresep'] 	= '#FFC09F';			}			else			{				$rs_eresep[$k]['fungsi'] = '<a href="#" onClick="javascript : if(confirm(\'hapus eresep ?\')) hapus_eresep_hangat(\''.$v['id_eresep'].'\');return false;">Hapus</a>';				$rs_eresep[$k]['bgcolor_riw_eresep'] 	= 'white';			}			*/			$checked = ($v['id_eresep']=='1') ? 'checked' : '';			$rs_eresep[$k]['fungsi'] = '<input type="checkbox" class="cb_eresep_pulang" id="cb_eresep_pulang[]" name="cb_eresep_pulang[]" value="'.$v['id_eresep'].'" '.$checked.' onClick="javascript : set_resep_pulang(\''.$v['id_eresep'].'\',this.checked);">';			$rs_eresep[$k]['bgcolor_riw_eresep'] = '#FFC09F';		}		$data = array(			'rs_eresep'	=> $rs_eresep,			'id_reg'		=> $id_reg		);		echo $this->load->view('list_riwayat_resep_online_pulang', $data, true);	}	public function list_riwayat_resep_online_det_v2($id_eresep,$is_html=false,$is_print='f')	{		$sql = "SELECT 	a.*,b.*						FROM 		soap_eresep a, soap_eresep_det b						WHERE 	a.id_eresep=b.id_eresep										AND a.id_eresep='".$id_eresep."'										AND b.is_racikan=0						ORDER BY a.id_eresep DESC						";		$query = $this->dbhis->query($sql);		$rs_eresep_det = $query->result_array();		## ------ RACIKAN --------------------