r;"><a href="#" onclick="javascript: if(confirm(\\\'Hapus ?\\\')) remove_row_draft(\\\'\'+ rand_no +\'\\\');return false;"><i class="fa fa-trash" style="color:red;"></i></a></td>		\n \' +				\' </tr>		\n \' ;				$( "#tbody_draft" ).append(tpl_row_copy_biasa);				$("#butt_simpan_resep").removeClass("hidden");				$("#batal_new_eresep").removeClass("hidden");			';		}		$tr_header_racikan = '';		foreach($rs_head as $k => $v)		{			$tr_header_racikan .= '				var id_num = $( "#id_num" ).val();				var num_resep_racikan = $( "#num_resep_racikan" ).val();				var tpl_row_copy = \'\n\' +					\' <tr id="row_racikan_\'+num_resep_racikan+\'"><td colspan="2">'.$v['name'].'	<input type="hidden" name="nama_racikan[\'+num_resep_racikan+\']" value="'.$v['name'].'"></td> \n \' +						\' <td>											<input type="text" name="jumlah_racikan[\'+num_resep_racikan+\']" value="'.$v['qty'].'" class="inp-short"></td> \n \' +						\' <td>											<input type="text" name="dosis_racikan[\'+num_resep_racikan+\']" value="'.$v['dosis'].'" class="inp-medium"></td> \n \' +						\' <td>											<input type="text" name="frekwensi_racikan[\'+num_resep_racikan+\']" value="'.$v['frekwensi'].'" class="inp-medium"></td> \n \' +						\' <td>											<input type="text" name="tme_racikan[\'+num_resep_racikan+\']" value="'.$v['tme'].'" class="inp-medium"></td> \n \' +						\' <td>											<input type="text" name="kemasan_racikan[\'+num_resep_racikan+\']" value="'.$v['jenis_obat'].'" class="inp-medium"></td> \n \' +						\' <td>											<input type="text" name="note_racikan[\'+num_resep_racikan+\']" value="'.$v['note'].'" class="inp-medium"></td> \n \' +						\' <td style="text-align:center;"><a href="#" onclick="javascript: if(confirm(\\\'Hapus ?\\\')) remove_row_resep_racikan(\\\'\'+num_resep_racikan+\'\\\');return false;"><i class="fa fa-trash" style="color:red;"></i></a></td> \n \' +					\' </tr>		\n \' ;				$("#tbody_draft_resep_racikan").append