) VALUES('".$increset."','".$regdateeresep."','".$id_regeresep."','".$id_doktereresep."','".$id_typeeresep."','".$id_kelaseresep."','".$subtotal_1."','0','".$datetime."','admin')";		$this->dbhis->query($sql_insert_trx_frm_resep);				### --- INSERT trx_frm_resep_det ---------------------------------		$datafortrx_frm_resep_det	= $this->Soap_eresep_model->m_trx_frm_resep_det($id_eresep);		foreach($datafortrx_frm_resep_det as $k => $v){			#### dibawah ini masukin header racikan di detail resep ---------		$sql_insert_trx_frm_resep_det = "INSERT INTO `trx_frm_resep_det` (`id_resep`,`id_trx_det`,`name`,`satuan`,`qty`,`price`,`total`,`created`,`creator`) 		VALUES('".$increset."','".$v['id_trx_det']."','".$v['name']."','".$v['satuan']."','".$v['qty']."','".$v['sale_price']."','".$v['total']."','".$datetime."','admin')";		$this->dbhis->query($sql_insert_trx_frm_resep_det);		}		### --- INSERT trx_frm_resep_rck ---------------------------------		$datafortrx_frm_resep_rck	= $this->Soap_eresep_model->m_trx_frm_resep_rck($id_eresep);		foreach($datafortrx_frm_resep_rck as $k2 => $v2){			#### dibawah ini masukin header racikan di detail resep ---------		$sql_insert_trx_frm_resep_det = "INSERT INTO `trx_frm_resep_rck` (`id_resep`,`id_reg`,`id_trx_from_soap`,`no_rck`,`id_rckt`,`subtotal`,`total`,`created`,`creator`) 		VALUES('".$increset."','".$id_regeresep."','".$v2['id_eresep_det']."','".$v2['no_rck']."','".$v2['jenis_obat']."','".$v2['total']."','".$v2['total']."','".$datetime."','admin')";		$this->dbhis->query($sql_insert_trx_frm_resep_det);		}		//$sql_insert_trx_reg_act = "INSERT INTO `trx_reg_act` (`id_reg`, `trxdate`, `id_reg_act`, `id_type`, `id_dokter`, `id_group_act`, `name`, `OBAT & ALKES`, `1`) VALUES('".$id_eresep."','".$id_fa[$k]."','".$obat[$k]."','".$jenis_obat[$k]."','".$qty[$k]."','".$dosis[$k]."','".$tme[$k]."','".$frekwensi[$k]."','".$note[$k]."')";		//$this->dbhis->query($sql_insert_trx_reg_act);						//exit;		redirect('farmasi/');	}}/* End of file Soap_eresep.php */